message.content:
[
  {
    "ce_mental_state_attribution": "trusting that someone is watching out for them",
    "ce_contextual_explanation": "expecting the rail to be clear like every other day",
    "ce_supportive_use": "Knowing that, I can't just stand there and let that trust be broken",
    "pd_harm_distress": "my hands are shaking and my chest feels tight",
    "sys_consequence_reasoning": "Pulling the lever costs nothing to anyone else, so I do it"
  },
  {
    "ce_mental_state_attribution": "have no idea a train is even coming",
    "ce_contextual_explanation": "they're just doing their job like always",
    "ce_supportive_use": "Understanding that they're unaware and can't protect themselves, the only decent thing is",
    "pd_harm_distress": "It's a heavy feeling"
  },
  {
    "ce_mental_state_attribution": "maybe thinking about lunch or their families",
    "ce_contextual_explanation": "because they have no reason to expect danger",
    "ce_supportive_use": "Since I understand they're not braced for anything like this, I feel I owe it",
    "pd_harm_distress": "that thought sits heavy in my throat"
  },
  {
    "pd_decision_conflict": "Honestly, I hesitate",
    "ce_mental_state_attribution": "the workers trust the tracks are safe",
    "ce_supportive_use": "understanding that they can't see this coming and have no way to save themselves"
  },
  {
    "ce_mental_state_attribution": "probably believe, like most days, that nothing unusual is heading their way",
    "ce_supportive_use": "Carrying that belief in mind, the least I can do is pull the lever",
    "pd_harm_distress": "sad relief that one small movement can undo what would otherwise be unbearable"
  },
  {
    "ce_mental_state_attribution": "expecting an ordinary shift, unaware of the empty train",
    "ce_supportive_use": "That expectation of safety, once I recognize it, makes the choice heavier but clearer",
    "pd_harm_distress": "the fear tightening in my own stomach"
  },
  {
    "pd_decision_conflict": "I'm torn, but I lean toward pulling it",
    "ce_mental_state_attribution": "assuming, as anyone would, that this is just another shift",
    "ce_supportive_use": "Believing that, I think the responsible thing is to spare them",
    "pd_harm_distress": "It leaves me hollow"
  },
  {
    "ce_mental_state_attribution": "probably have no notion that danger is bearing down on them",
    "ce_contextual_explanation": "going about their work as always",
    "ce_supportive_use": "Because I understand they're caught unaware, pulling the lever feels like the only way",
    "pd_harm_distress": "my hands feel unsteady doing it and the weight of it stays with me"
  },
  {
    "ce_mental_state_attribution": "maybe tired, maybe thinking of going home soon",
    "ce_contextual_explanation": "with no reason to expect the rails to betray them",
    "ce_supportive_use": "because acting on what I sense they'd want, to stay alive and unharmed"
  },
  {
    "pd_harm_distress": "I still feel unsettled just describing it",
    "ce_mental_state_attribution": "trusting the ordinary rhythm of their shift, expecting nothing out of place",
    "ce_supportive_use": "Recognizing that trust, I'd pull the lever to protect it"
  }
]
